package dev.pedro.learning.ecommerce.payment.domain;import io.quarkus.hibernate.orm.panache.PanacheRepositoryBase;import jakarta.enterprise.context.ApplicationScoped;import java.util.UUID;@ApplicationScoped public class PaymentRepository implements PanacheRepositoryBase<PaymentEntity,UUID>{public PaymentEntity findByOrderId(UUID orderId){return find("orderId",orderId).firstResult();}}